#include "kbm_text.h"

#include "fh2_game.h"
#include "translations.h"  // generated by build.py from src/translations.json

unsigned kbm_text_count(void) { return ARRAY_COUNT(kbm_texts); }

const KbmText *kbm_text_at(unsigned index) { return index < ARRAY_COUNT(kbm_texts) ? &kbm_texts[index] : NULL; }

const KbmText *kbm_text_for(const char *code) {
    for (unsigned i = 0; code && i < ARRAY_COUNT(kbm_texts); ++i)
        if (text_equal_ignore_case(code, kbm_texts[i].code)) return &kbm_texts[i];
    return NULL;
}

/* The language code the game uses for its text ("EN", "PL", "CHT", ...): a
   short std::string at manager+0x30, as Extra Options reads it
   (common/include/fh2_game.h). */
const KbmText *kbm_text(unsigned char *game_image) {
    char code[4];
    const KbmText *text = fh2_game_language(game_image, code) ? kbm_text_for(code) : NULL;
    return text ? text : &kbm_texts[0];
}

#ifdef KBM_TEST
__declspec(dllexport) unsigned KbmTestLanguages(void) { return kbm_text_count(); }
__declspec(dllexport) const char *KbmTestLanguage(unsigned index) {
    return index < kbm_text_count() ? kbm_texts[index].code : NULL;
}
__declspec(dllexport) const char *KbmTestTitle(unsigned char *game_image) { return kbm_text(game_image)->keyboard_mouse; }
/* 1 when every text of every language is there. */
__declspec(dllexport) int KbmTestTextComplete(void) {
    for (unsigned i = 0; i < kbm_text_count(); ++i) {
        const KbmText *t = &kbm_texts[i];
        int ok = t->keyboard_mouse && t->kbm_reset && t->kbm_reset_description && t->on && t->off;
        for (unsigned r = 0; r < KBM_TEXT_ROWS; ++r) ok &= t->kbm_names[r] && t->kbm_descriptions[r];
        for (unsigned a = 0; a < KBM_TEXT_ACTIONS; ++a) ok &= t->kbm_actions[a] != NULL;
        for (unsigned m = 0; m < 3; ++m) ok &= t->kbm_modes[m] != NULL;
        for (unsigned l = 0; l < KBM_LABEL_COUNT; ++l) ok &= t->kbm_labels[l] != NULL;
        ok &= t->kbm_key_descriptions[0] && t->kbm_key_descriptions[1];
        if (!ok) return 0;
    }
    return 1;
}
#endif
